441	func (h *Handler) Cleanup() error {
442		err := h.cleanupConnections()
443	
444		// remove hosts from our config from the pool
445		for _, upstream := range h.Upstreams {
446			_, _ = hosts.Delete(upstream.String())
447		}
448	
449		return err
450	}
