599	// proxyLoopIteration implements an iteration of the proxy loop. Despite the enormous amount of local state
600	// that has to be passed in, we brought this into its own method so that we could run defer more easily.
601	// It returns true when the loop is done and should break; false otherwise. The error value returned should
602	// be assigned to the proxyErr value for the next iteration of the loop (or the error handled after break).
603	func (h *Handler) proxyLoopIteration(r *http.Request, origReq *http.Request, w http.ResponseWriter, proxyErr error, start time.Time, retries int,
604		repl *caddy.Replacer, reqHeader http.Header, reqHost string, next caddyhttp.Handler,
605	) (bool, error) {
606		// get the updated list of upstreams
607		upstreams := h.Upstreams
608		if h.DynamicUpstreams != nil {
609			if retries > 0 {
610				// after a failure (and thus during a retry), give dynamic upstream modules an opportunity
611				// to purge their relevant cache entries so we don't keep retrying bad upstreams
612				if cachingDynamicUpstreams, ok := h.DynamicUpstreams.(CachingUpstreamSource); ok {
613					if err := cachingDynamicUpstreams.ResetCache(r); err != nil {
614						if c := h.logger.Check(zapcore.ErrorLevel, "failed clearing dynamic upstream source's cache"); c != nil {
615							c.Write(zap.Error(err))
616						}
617					}
618				}
619			}
620			dUpstreams, err := h.DynamicUpstreams.GetUpstreams(r)
621			if err != nil {
622				if c := h.logger.Check(zapcore.ErrorLevel, "failed getting dynamic upstreams; falling back to static upstreams"); c != nil {
623					c.Write(zap.Error(err))
624				}
625			} else {
626				upstreams = dUpstreams
627				for _, dUp := range dUpstreams {
628					h.provisionUpstream(dUp, true)
629				}
630				if c := h.logger.Check(zapcore.DebugLevel, "provisioned dynamic upstreams"); c != nil {
631					c.Write(zap.Int("count", len(dUpstreams)))
632				}
633			}
634		}
635	
636		// choose an available upstream
637		upstream := h.LoadBalancing.SelectionPolicy.Select(upstreams, r, w)
638		if upstream == nil {
639			if proxyErr == nil {
640				proxyErr = caddyhttp.Error(http.StatusServiceUnavailable, errNoUpstream)
641			}
642			if !h.LoadBalancing.tryAgain(h.ctx, start, retries, proxyErr, r, h.logger) {
643				return true, proxyErr
644			}
645			return false, proxyErr
646		}
647	
648		// the dial address may vary per-request if placeholders are
649		// used, so perform those replacements here; the resulting
650		// DialInfo struct should have valid network address syntax
651		dialInfo, err := upstream.fillDialInfo(repl)
652		if err != nil {
653			return true, fmt.Errorf("making dial info: %v", err)
654		}
655	
656		if c := h.logger.Check(zapcore.DebugLevel, "selected upstream"); c != nil {
657			c.Write(
658				zap.String("dial", dialInfo.Address),
659				zap.Int("total_upstreams", len(upstreams)),
660			)
661		}
662	
663		// attach to the request information about how to dial the upstream;
664		// this is necessary because the information cannot be sufficiently
665		// or satisfactorily represented in a URL
666		caddyhttp.SetVar(r.Context(), dialInfoVarKey, dialInfo)
667	
668		// set placeholders with information about this upstream
669		repl.Set("http.reverse_proxy.upstream.address", dialInfo.String())
670		repl.Set("http.reverse_proxy.upstream.hostport", dialInfo.Address)
671		repl.Set("http.reverse_proxy.upstream.host", dialInfo.Host)
672		repl.Set("http.reverse_proxy.upstream.port", dialInfo.Port)
673		repl.Set("http.reverse_proxy.upstream.requests", upstream.Host.NumRequests())
674		repl.Set("http.reverse_proxy.upstream.max_requests", upstream.MaxRequests)
675		repl.Set("http.reverse_proxy.upstream.fails", upstream.Host.Fails())
676	
677		// mutate request headers according to this upstream;
678		// because we're in a retry loop, we have to copy headers
679		// (and the r.Host value) from the original so that each
680		// retry is identical to the first. If either transport or
681		// user ops exist, apply them in order (transport first,
682		// then user, so user's config wins).
683		var userOps *headers.HeaderOps
684		if h.Headers != nil {
685			userOps = h.Headers.Request
686		}
687		transportOps := h.transportHeaderOps
688		if transportOps != nil || userOps != nil {
689			r.Header = make(http.Header)
690			copyHeader(r.Header, reqHeader)
691			r.Host = reqHost
692			if transportOps != nil {
693				transportOps.ApplyToRequest(r)
694			}
695			if userOps != nil {
696				userOps.ApplyToRequest(r)
697			}
698		}
699	
700		// proxy the request to that upstream
701		proxyErr = h.reverseProxy(w, r, origReq, repl, dialInfo, next)
702		if proxyErr == nil || errors.Is(proxyErr, context.Canceled) {
703			// context.Canceled happens when the downstream client
704			// cancels the request, which is not our failure
705			return true, nil
706		}
707	
708		// if the roundtrip was successful, don't retry the request or
709		// ding the health status of the upstream (an error can still
710		// occur after the roundtrip if, for example, a response handler
711		// after the roundtrip returns an error)
712		if succ, ok := proxyErr.(roundtripSucceededError); ok {
713			return true, succ.error
714		}
715	
716		// remember this failure (if enabled); response-based retries
717		// are not counted as failures since the upstream did respond
718		// successfully - only the response content triggered a retry
719		if _, isRetryableResponse := proxyErr.(retryableResponseError); !isRetryableResponse {
720			h.countFailure(upstream)
721		}
722	
723		// if we've tried long enough, break
724		if !h.LoadBalancing.tryAgain(h.ctx, start, retries, proxyErr, r, h.logger) {
725			return true, proxyErr
726		}
727	
728		return false, proxyErr
729	}
