// selectUpstream applies the configured selection policy to pool, excluding
// upstreams that have already been attempted for the current request (keyed by
// their resolved dial address). This keeps retry semantics independent of the
// policy: for example, "first" would otherwise re-select the same first
// upstream on every attempt, and random or round_robin policies do not promise
// a different upstream either. The exclusion set is per-request and carries no
// health state, so it never affects subsequent client requests. If no
// unattempted upstream remains, nil is returned and the caller treats the
// request the same as when no upstream is available.
func (h *Handler) selectUpstream(pool UpstreamPool, r *http.Request, w http.ResponseWriter,
	repl *caddy.Replacer, triedUpstreams map[string]struct{},
) *Upstream {
	policy := h.LoadBalancing.SelectionPolicy
	if len(triedUpstreams) == 0 {
		return policy.Select(pool, r, w)
	}
	candidates := make(UpstreamPool, 0, len(pool))
	for _, u := range pool {
		// resolve the same dial address that proxyLoopIteration uses
		// below; an unresolvable address is left in as a candidate so
		// that its existing, terminal configuration error is surfaced
		di, err := u.fillDialInfo(repl)
		if err != nil {
			candidates = append(candidates, u)
			continue
		}
		if _, tried := triedUpstreams[di.Address]; !tried {
			candidates = append(candidates, u)
		}
	}
	if len(candidates) == 0 {
		return nil
	}
	return policy.Select(candidates, r, w)
}

